import{_ as a,o as s,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"PulseOut 输出脉冲","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/PulseOut.md","filePath":"3. 指令/4. IO 指令/PulseOut.md","lastUpdated":1778862643000}'),d={name:"3. 指令/4. IO 指令/PulseOut.md"};function r(n,t,l,h,o,p){return s(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="pulseout-输出脉冲" tabindex="-1">PulseOut 输出脉冲 <a class="header-anchor" href="#pulseout-输出脉冲" aria-label="Permalink to &quot;PulseOut 输出脉冲&quot;">​</a></h1><p>该指令用于在指定的数字量输出端口输出一个具有固定时长和状态的脉冲信号。常用于触发外部设备的单次动作，如气缸换向、相机快门触发或给 PLC 发送握手脉冲。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>PulseOut (DOUT, VALUE, T, INTERENABLE)</code></p><p><code>PulseOut(输出端口, 触发状态, 持续时间, 打断使能)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>DOUT</td><td>DO</td><td>用于指定输出脉冲的数字量输出端口</td><td>必填</td></tr><tr><td>VALUE</td><td>int</td><td>脉冲状态（1：高电平脉冲，0：低电平脉冲）</td><td>必填</td></tr><tr><td>T</td><td>int</td><td>脉冲信号持续时间，单位 ms</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int</td><td>暂停时是否继续输出（0：持续输出不受暂停影响，1：暂停时停止输出）</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PulseOut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DO1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在数字量输出变量 <strong>DO1</strong> 绑定端口输出 <strong>500ms</strong> 的脉冲信号，脉冲幅值为 <strong>1</strong>。若脉冲输出期间暂停程序，则端口停止输出，在程序恢复启动后恢复脉冲输出。</p>',13)])])}const k=a(d,[["render",r]]);export{c as __pageData,k as default};
